def solution(input_str):
    import sys
    import os

    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    d = [int(x) for x in lines[1].split()]

    h = [int(x) for x in lines[2].split()]

    queries = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        a, b = int(parts[0]), int(parts[1])
        queries.append((a, b))

    # Prefix distances (cumulative from tree 1)
    # prefix_dist[i] = distance from tree 1 to tree i (1-indexed)
    prefix_dist = [0] * (n + 1)
    for i in range(1, n):
        prefix_dist[i + 1] = prefix_dist[i] + d[i - 1]

    total_dist = prefix_dist[n]  # Distance from tree 1 to tree n plus d[n-1] -> d[n]
    total_dist += d[n - 1]  # Distance from tree n to tree 1

    def get_dist(i, j):
        """Get distance between tree i and tree j, avoiding blocked arc"""
        idx_i, idx_j = i - 1, j - 1
        if idx_i == 0:
            idx_i = n
        if idx_j == 0:
            idx_j = n

        fwd = abs(prefix_dist[i] - prefix_dist[j])
        bwd = total_dist - fwd
        return min(fwd, bwd)

    def get_forbidden_range(a, b):
        """Get set of forbidden tree indices (1-indexed)"""
        if a <= b:
            return set(range(a, b + 1))
        else:
            return set(range(a, n + 1)) | set(range(1, b + 1))

    def get_valid_trees(a, b):
        """Get list of valid (non-forbidden) tree indices (1-indexed)"""
        forbidden = get_forbidden_range(a, b)
        return [i for i in range(1, n + 1) if i not in forbidden]

    # Separate heights for 0-indexed access
    h_arr = list(h)  # h[i-1] for tree i

    results = []
    for a, b in queries:
        valid = get_valid_trees(a, b)

        if len(valid) < 2:
            # This shouldn't happen per problem constraints
            results.append("0")
            continue

        best_energy = 0

        # Check all pairs - use optimization when possible
        n_valid = len(valid)
        for i in range(n_valid):
            xi = valid[i]
            hi_val = h_arr[xi - 1]

            for j in range(i + 1, n_valid):
                xj = valid[j]
                hj_val = h_arr[xj - 1]

                dist = get_dist(xi, xj)
                energy = 2 * (hi_val + hj_val) + dist

                if energy > best_energy:
                    best_energy = energy

        results.append(str(best_energy))

    return '\n'.join(results)
