def solution(input_string):
    import itertools

    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    A = [list(map(int, lines[i + 1].split())) for i in range(n)]
    B = [list(map(int, lines[n + 1 + i].split())) for i in range(n)]

    if A == B:
        return "0"

