        if sorted([row[j] for row in A]) != sorted([row[j] for row in B]):
            return "-1"

    def apply(table, cols):
        idx = list(range(len(table)))
        for c in cols:
            idx.sort(key=lambda i: table[i][c])
        return [table[i] for i in idx]

    for s in itertools.permutations(range(m), 1):
        if apply(A, list(s)) == B:
            return f"1\n{list(s)[0] + 1}"

    for s in itertools.permutations(range(m), 2):
        if apply(A, list(s)) == B:
            return f"2\n{list(s)[0] + 1} {list(s)[1] + 1}"

    for s in itertools.permutations(range(m), 3):
        if apply(A, list(s)) == B:
            return f"3\n{list(s)[0] + 1} {list(s)[1] + 1} {list(s)[2] + 1}"

    for s in itertools.permutations(range(m), min(m, 10)):
        if apply(A, list(s)) == B:
            return f"{len(s)}\n{' '.join(map(str, [c+1 for c in s]))}"

